#!/usr/bin/env python3
"""Build the standalone mobile-first EFL Championship 2026/27 dashboard."""
import csv,json
from pathlib import Path
ROOT=Path(__file__).parent
D=ROOT/'data'
def rows(file):
    with open(D/file,encoding='utf-8',newline='') as f:return list(csv.DictReader(f))
fixtures=[]
for r in rows('fixtures_results_2026_27.csv')+rows('upcoming_fixtures_through_2026-11-01.csv'):
    fixtures.append({'id':r['fixture_id'],'date':r['date_utc'],'home':r['home'],'away':r['away'],'hg':int(r['home_goals']) if r['home_goals'] else None,'ag':int(r['away_goals']) if r['away_goals'] else None,'status':r['status'],'url':r['source_url']})
clubs=[]
for r in rows('efl_official_table.csv'):
    clubs.append({'name':r['team'],'pos':int(r['position']),'deduction':-4 if r['team']=='Southampton' else 0})
fixtures_json=json.dumps(fixtures,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
clubs_json=json.dumps(clubs,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
